package dev.zomboidmelee.boxing;
import net.minecraft.core.BlockPos;import net.minecraft.world.phys.AABB;import dev.zomboidmelee.boxing.ParkourChecks25.*;
public class SlabRegression27 {
 static int n;static void ok(boolean x,String message){n++;if(!x)throw new AssertionError(message);}
 static class Partial extends Block {double bottom,top;Partial(double bottom,double top){super(true);this.bottom=bottom;this.top=top;}public Shape getCollisionShape(Object level,BlockPos p){return new Shape(new AABB(0,bottom,0,1,top,1));}}
 static class SlabWorld extends World {public boolean noCollision(Object p,AABB box){if(box.minY<0)return false;for(var entry:blocks.entrySet()){BlockPos b=entry.getKey();AABB shape=entry.getValue().getCollisionShape(this,b).bounds();if(hit(box,new AABB(b.x()+shape.minX,b.y()+shape.minY,b.z()+shape.minZ,b.x()+shape.maxX,b.y()+shape.maxY,b.z()+shape.maxZ)))return false;}return true;}}
 static Player elevated(){Player p=new Player();p.physics=new SlabWorld();p.py=.5;p.physics.blocks.put(new BlockPos(0,0,0),new Partial(0,.5));p.physics.blocks.put(new BlockPos(0,0,1),new Block(true));p.physics.blocks.put(new BlockPos(0,1,1),new Block(true));p.physics.blocks.put(new BlockPos(0,2,1),new Partial(0,.5));Parkour20.tick(p,true);p.py=.9;p.ground=false;return p;}
 public static void main(String[]args){Player p=elevated();Move25.request(p,3);ok(Parkour20.active(p),"starting on slab must detect upper slab two blocks above feet");ok(Math.abs(Parkour20.ACTIVE.get(p).y-2.54)<.001,"landing height follows slab collision top");int steps=0;while(Parkour20.active(p)&&steps++<32){Parkour20.tick(p,true);p.step();}ok(p.py>=2.5&&Math.abs(p.pz-1.5)<.2,"mantle reaches slab from fractional starting height");
 Player half=new Player();half.physics=new SlabWorld();half.physics.blocks.put(new BlockPos(0,0,1),new Partial(0,.5));Parkour20.tick(half,true);half.py=.7;half.ground=false;Move25.request(half,3);ok(Parkour20.active(half),"half slab remains reachable when jump is already above its surface");ok(Math.abs(Parkour20.ACTIVE.get(half).y-.54)<.001,"low slab is not treated as a full cube");
 Player upper=new Player();upper.physics=new SlabWorld();upper.physics.blocks.put(new BlockPos(0,0,1),new Partial(.5,1));Parkour20.tick(upper,true);upper.py=.4;upper.ground=false;Move25.request(upper,3);ok(Parkour20.active(upper)&&Math.abs(Parkour20.ACTIVE.get(upper).y-1.04)<.001,"upper slab uses its actual collision top");
 Player blocked=elevated();blocked.physics.blocks.put(new BlockPos(0,4,1),new Block(true));Move25.request(blocked,3);ok(!Parkour20.active(blocked),"slab fix still rejects blocked headroom");Player tooHigh=elevated();tooHigh.physics.blocks.put(new BlockPos(0,2,1),new Block(true));Move25.request(tooHigh,3);ok(!Parkour20.active(tooHigh),"fractional start does not allow climbing more than two blocks");System.out.println("FRACTIONAL_GROUND_LOWER_UPPER_SLAB_COLLISION_HEADROOM_CHECKS="+n);}
}
